class Cuenta:
    def __init__(self):
        self._saldo = 0

    @property
    def saldo(self):
        return self._saldo

    def ingresar(self, cantidad):
        if cantidad <= 0:
            return False
        self._saldo += cantidad
        return True

cuenta = Cuenta()
print(cuenta.ingresar(-5), cuenta.saldo)
print(cuenta.ingresar(10), cuenta.saldo)
